#!/usr/bin/env python3
"""Check that every graphml says truthfully how it was made.

Each spec-sdl graphml carries exactly one provenance comment:

- yEd's own "<!--Created by yEd ...-->", only for files listed in
  tools/provenance/yed-drawn.txt (drawn by a person in yEd); or
- an agent marker, for a file generated by an agent from the palette:
  "<!--Agent-generated by <who> on YYYY-MM-DD; not drawn in yEd.-->"

An agent that copies palette nodes also copies yEd's comment, which would
make the file claim a provenance it doesn't have. This check fails on that,
on a missing or doubled marker, and on a stale entry in the list. It scans
every graphml in the repository (any case of extension), and treats any
"Created by yEd" comment as a yEd claim, whatever its spacing or version.

Usage: python3 tools/provenance/check_graphml_provenance.py [repo-root]
"""
import pathlib
import re
import sys
import unicodedata

# Tolerant on purpose: any comment that mentions yEd as the creator counts
# as a yEd claim, whatever its spacing, case, version or other text up to
# the closing "-->" (so "(a > b)" inside it can't end the match early).
YED = re.compile(r"<!--\s*Created\s+by\s+yEd\b.*?-->", re.IGNORECASE | re.DOTALL)

# Latin lookalikes that NFKC leaves alone (Cyrillic and Greek letters that
# render like Latin ones), folded so "yЕd" with a Cyrillic E still matches.
CONFUSABLES = str.maketrans({
    "А": "A", "В": "B", "С": "C", "Е": "E", "Н": "H", "І": "I", "Ј": "J", "К": "K", "М": "M",
    "О": "O", "Р": "P", "Ѕ": "S", "Т": "T", "Х": "X", "Ү": "Y",
    "а": "a", "с": "c", "е": "e", "і": "i", "ј": "j", "о": "o", "р": "p", "ѕ": "s", "х": "x", "у": "y", "ԁ": "d",
    "Α": "A", "Β": "B", "Ε": "E", "Ζ": "Z", "Η": "H", "Ι": "I", "Κ": "K", "Μ": "M", "Ν": "N", "Ο": "O",
    "Ρ": "P", "Τ": "T", "Υ": "Y", "Χ": "X", "ο": "o", "ν": "v",
})


def normalise(text: str) -> str:
    """NFKC, then fold Latin lookalikes, so look-alike spellings can't slip past."""
    return unicodedata.normalize("NFKC", text).translate(CONFUSABLES)
AGENT = re.compile(r"<!--Agent-generated by [^;<>]+ on \d{4}-\d{2}-\d{2}; not drawn in yEd\.-->")
AGENT_LOOSE = re.compile(r"<!--\s*Agent[\s-]*generated", re.IGNORECASE)


def main() -> int:
    root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else ".")
    listed = {
        line.strip()
        for line in (root / "tools/provenance/yed-drawn.txt").read_text().splitlines()
        if line.strip() and not line.startswith("#")
    }
    # Every graphml in the repository, whatever the case of its extension,
    # not only those under spec-sdl/.
    files = sorted(
        p.relative_to(root).as_posix()
        for p in root.rglob("*")
        if p.is_file() and p.suffix.lower() == ".graphml"
        and ".git" not in p.relative_to(root).parts
    )
    errors = []
    for rel in files:
        text = normalise((root / rel).read_text(encoding="utf-8"))
        yed = len(YED.findall(text))
        agent = len(AGENT.findall(text))
        if AGENT_LOOSE.search(text) and agent == 0:
            errors.append(f"{rel}: malformed agent marker; use <!--Agent-generated by <who> on YYYY-MM-DD; not drawn in yEd.-->")
        elif yed + agent != 1:
            errors.append(f"{rel}: needs exactly one provenance comment (found {yed} yEd, {agent} agent)")
        elif yed and rel not in listed:
            errors.append(f"{rel}: claims to be created by yEd but is not in tools/provenance/yed-drawn.txt. "
                          "If an agent made it, replace yEd's comment with the agent marker.")
        elif agent and rel in listed:
            errors.append(f"{rel}: listed in tools/provenance/yed-drawn.txt but carries an agent marker")
        else:
            print(f"ok    {rel}  ({'yEd' if yed else 'agent'})")
    for rel in sorted(listed - set(files)):
        errors.append(f"tools/provenance/yed-drawn.txt: {rel} does not exist")
    for e in errors:
        print(f"::error::{e}")
    print(f"{len(files)} graphml, {len(errors)} provenance error(s)")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
